using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using IdleRestaurant;using UnityEngine;
public sealed class CleanupAudio053:MonoBehaviour {public bool active;public int channels;readonly List<float> data=new List<float>();readonly object sync=new object();void OnAudioFilterRead(float[] a,int c){if(active)lock(sync){channels=c;data.AddRange(a);}}public void Begin(){lock(sync)data.Clear();active=true;}public int End(string file){active=false;lock(sync){var a=data.ToArray();byte[] b=new byte[a.Length*4];Buffer.BlockCopy(a,0,b,0,b.Length);File.WriteAllBytes(file,b);return a.Length;}}}
public static class LiveCleanup053 {
 const string Root="/Users/playnoob/Desktop/Mahnul/GPT/restaurant-v053-cleanup/live";static RestaurantApp app;static CleanupAudio053 audio;static List<string> checks=new List<string>();static List<object> segments=new List<object>(),events=new List<object>();static string error="";
 static void Check(bool v,string s){if(!v)throw new Exception(s);checks.Add(s);}
 public static void Main(){Directory.CreateDirectory(Root);app=UnityEngine.Object.FindAnyObjectByType<RestaurantApp>();Application.runInBackground=true;Time.timeScale=1;app.StartCoroutine(Guard(Run()));}
 static IEnumerator Guard(IEnumerator e){var stack=new Stack<IEnumerator>();stack.Push(e);while(stack.Count>0){object value=null;bool more;try{more=stack.Peek().MoveNext();if(more)value=stack.Peek().Current;}catch(Exception ex){error=ex.ToString();File.WriteAllText(Root+"/error.txt",error);break;}if(!more){(stack.Pop() as IDisposable)?.Dispose();continue;}if(value is IEnumerator sub)stack.Push(sub);else yield return value;}while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();}
 static IEnumerator Shot(string name){yield return new WaitForEndOfFrame();var t=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,t.width,t.height),0,0);t.Apply();File.WriteAllBytes(Root+"/"+name+".png",t.EncodeToPNG());UnityEngine.Object.Destroy(t);}
 static IEnumerator Record(string name,float duration){string dir=Root+"/"+name;Directory.CreateDirectory(dir);var frames=new List<object>();float start=Time.realtimeSinceStartup;int n=0;audio.Begin();while(Time.realtimeSinceStartup-start<duration){yield return new WaitForEndOfFrame();var t=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,t.width,t.height),0,0);t.Apply();string f=(n++).ToString("D4")+".jpg";File.WriteAllBytes(dir+"/"+f,t.EncodeToJPG(90));UnityEngine.Object.Destroy(t);frames.Add(new{file=f,seconds=Time.realtimeSinceStartup-start,frame=Time.frameCount});yield return new WaitForSecondsRealtime(.04f);}int samples=audio.End(dir+"/audio.f32");File.WriteAllText(dir+"/frames.json",Newtonsoft.Json.JsonConvert.SerializeObject(frames));segments.Add(new{name,duration=Time.realtimeSinceStartup-start,frames=n,samples,channels=audio.channels,sampleRate=AudioSettings.outputSampleRate});File.WriteAllText(Root+"/segments.json",Newtonsoft.Json.JsonConvert.SerializeObject(segments));}
 static IEnumerator Run(){string old=Newtonsoft.Json.JsonConvert.SerializeObject(app.Game.State);bool success=false;audio=app.gameCamera.gameObject.AddComponent<CleanupAudio053>();try{
 app.Game.State=new RestaurantGame(app.catalog).State;app.Game.State.introComplete=true;app.Game.State.guideStep=6;app.Navigate("play");app.world.Show(0);app.Game.BeginService();double start=app.Game.State.seconds;
 while(app.Game.State.seconds-start<110)yield return null;
 var state=app.Game.State;var dirt=state.outlets[0].dirt;Check(app.Game.TotalWaves()>=1,"Automatic services continue while dirt is ignored");Check(dirt.Any(m=>m.kind==0)&&dirt.Any(m=>m.kind==1)&&dirt.Any(m=>m.kind==2),"Finished meals, occasional tissue and paper cups appear naturally");Check(state.cleanupVisits==0,"Ignoring dirt never starts a janitor or changes rewards");yield return Shot("before-cleanup");yield return Record("01-guests-and-dirt",7);
 var view=app.world.room.GetComponent<RestaurantCleanupView>();var mess=dirt.First();Vector3 p=app.world.room.TransformPoint(new Vector3(mess.x,mess.kind==0?.85f:0,mess.z));Vector2 tap=app.gameCamera.WorldToScreenPoint(p);app.Navigate("map");yield return null;Check(!view.TryTap(tap),"Map navigation blocks world cleanup taps");app.Navigate("play");yield return null;int[] batch=dirt.Select(m=>m.id).ToArray();double reward=app.Game.NetworkIncome()*1.5;Check(view.TryTap(tap),"Visible dirt accepts the same screen-position tap path as touch");Check(state.cleanupJob.active&&state.cleanupVisits==0,"Tap summons an actual janitor before payment");Check(Math.Abs(state.cleanupJob.reward-reward)<.000001,"Live visit snapshots 1.5 times displayed income/min");Check(!view.TryTap(tap),"Repeated active taps cannot spawn another janitor");events.Add(new{kind="dispatched",state.seconds,reward,batch});
 yield return Record("02-janitor-visit",38);
 while(state.cleanupJob.active)yield return null;
 Check(state.cleanupVisits==1&&state.cleanupJob.paid,"Actual janitor finishes one visit and awards once");Check(!dirt.Any(m=>batch.Contains(m.id)),"All plates and floor litter present at dispatch have been cleaned");Check(app.Game.CleanupWait>0&&app.Game.CleanupWait<=90,"Reward starts the confirmed global 90-second repeat interval");yield return Shot("after-cleanup");
 while(dirt.Count==0)yield return null;mess=dirt.First();tap=app.gameCamera.WorldToScreenPoint(app.world.room.TransformPoint(new Vector3(mess.x,mess.kind==0?.85f:0,mess.z)));Check(view.TryTap(tap)&&state.queuedCleanup==0&&!state.cleanupJob.active,"A cooldown tap queues one later visit without early payment");double wait=app.Game.CleanupWait;float w=Time.realtimeSinceStartup;while(Time.realtimeSinceStartup-w<Math.Min(4,wait-1))yield return null;Check(!state.cleanupJob.active&&state.cleanupVisits==1,"Queued cleanup waits instead of bypassing the repeat interval");yield return Shot("cooldown-queued");while(!state.cleanupJob.active)yield return null;Check(state.cleanupJob.id==2,"Queued second janitor dispatches automatically after the interval");yield return Record("03-second-janitor",12);yield return Shot("second-janitor");while(state.cleanupJob.active)yield return null;Check(state.cleanupVisits==2,"Second visit also completes with one payout");Check(app.Game.TotalWaves()>=4,"Meal services keep running independently throughout both cleaning visits");success=true;
 }finally{audio.active=false;UnityEngine.Object.Destroy(audio);File.WriteAllText(Root+"/LiveCleanupVerification.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status=success?"PASS":"FAIL",error,utc=DateTime.UtcNow,timeScale=Time.timeScale,seconds=app.Game.State.seconds,waves=app.Game.TotalWaves(),visits=app.Game.State.cleanupVisits,checks,events,scope="Live Unity at normal speed; fresh model with tutorial skipped for focused optional-cleanup checks. No currency injection. Separate fresh-save pacing session required."},Newtonsoft.Json.Formatting.Indented));app.Game.State=new RestaurantGame(app.catalog,Newtonsoft.Json.JsonConvert.DeserializeObject<SaveState>(old)).State;app.Navigate("play");app.world.Show(app.Game.State.selected);app.Save();File.WriteAllText(Root+"/status.txt",success?"COMPLETE":"FAILED");}}
}
